function S=w2e_summarize_all(PairResults,Samples,O,Rmc)
%W2E_SUMMARIZE_ALL Frozen method and paired descriptive summaries.
N=numel(PairResults);A=repmat(w2e_empty_run(),N,1);B=A;PR=repmat(w2e_empty_pair_row(),N,1);for k=1:N,A(k)=PairResults{k}.Proposed;B(k)=PairResults{k}.MatchedQP;PR(k)=PairResults{k}.Pair;end
S=struct();S.N=N;S.ProtocolID=O.ProtocolID;S.Proposed=methodSummary(A,'Proposed');S.MatchedQP=methodSummary(B,'MatchedQP');
S.Pair.NBothCompleted=sum([PR.BothCompleted]);S.Pair.NBothHardFeasible=sum([PR.BothHardFeasible]);S.Pair.NBothCorePass=sum([PR.BothCorePass]);S.Pair.NBothCertifiedDomain=sum([PR.BothCertifiedDomain]);S.Pair.NProposedOnlyCorePass=sum([PR.ProposedOnlyCorePass]);S.Pair.NQPOnlyCorePass=sum([PR.QPOnlyCorePass]);S.Pair.NNeitherCorePass=sum([PR.NeitherCorePass]);S.Pair.NExecutionDiscordant=sum([PR.ExecutionDiscordant]);S.Pair.PerformancePopulation='BothCorePass only; failed/gate-failed pairs receive no numeric penalty.';
metrics={'dPosRMSFull_m','dPosPeakFull_m','dPosRMSLate_m','dPosPeakLate_m','dIntervention_pp','dMeanCorrectionNorm','dIntegratedObjective_s','dMaxAttitudeTube_deg','dMaxMomentResidual_Nm','dMaxThrustRate_Nps'};MR=cell(numel(metrics),1);
for j=1:numel(metrics),v=[PR.(metrics{j})].';v=v(isfinite(v));q=w2e_quantiles(v,[.05 .25 .50 .75 .95]);tol=1e-12;MR{j}=struct('Metric',metrics{j},'N',numel(v),'Mean_QPminusProposed',mean(v),'Q05',q(1),'Q25',q(2),'Median',q(3),'Q75',q(4),'Q95',q(5),'FracQPLower',mean(v<-tol),'FracProposedLower',mean(v>tol),'FracTie',mean(abs(v)<=tol));end
S.PairedMetricRows=MR;S.windPeakBoundRange=[min([Samples.windPeakBound]) max([Samples.windPeakBound])];S.aeroMaxDeviationPctRange=[min([Samples.aeroMaxDeviationPct]) max([Samples.aeroMaxDeviationPct])];S.Seed=Rmc.seed;
% Aggregate role counts over completed runs; trial incidence is also retained.
names=w2b_row_names();RR=cell(36,1);q=0;for im=1:2,if im==1,Runs=A;m='Proposed';else,Runs=B;m='MatchedQP';end;comp=[Runs.Completed];for j=1:18,q=q+1;counts=arrayfun(@(r)r.RoleCount(j),Runs);bind=arrayfun(@(r)r.BindingCount(j),Runs);RR{q}=struct('Method',m,'RowIndex',j,'Row',names{j},'CompletedTrials',sum(comp),'TotalSelectionRoleSamples',sum(counts(comp)),'TrialsWithSelectionRole',sum(counts(comp)>0),'TotalBindingSamples',sum(bind(comp)),'TrialsWithBinding',sum(bind(comp)>0));end;end;S.RoleRows=RR;
end
function M=methodSummary(Runs,name)
M=struct();M.Method=name;M.N=numel(Runs);M.NCompleted=sum([Runs.Completed]);M.NHardFeasible=sum([Runs.HardFeasible]);M.NCorePass=sum([Runs.CorePass]);M.NCertifiedDomain=sum([Runs.CertifiedDomain]);M.NDomainExit=sum([Runs.DomainExit]);M.NNumericalFailure=sum([Runs.NumericalFailure]);M.NCompletedCoreGateFail=sum([Runs.Completed]&~[Runs.CorePass]);M.NRawChartExit=sum(strcmp({Runs.FailureClass},'RAW_COMMAND_CHART_EXIT'));M.NBackupExit=sum(strcmp({Runs.FailureClass},'PROPOSED_BACKUP_FEASIBILITY_EXIT'));M.NInversionExit=sum(strcmp({Runs.FailureClass},'REFERENCE_INVERSION_DOMAIN_EXIT'));M.NFeedbackInversionExit=sum(strcmp({Runs.FailureClass},'FEEDBACK_INVERSION_DOMAIN_EXIT'));M.NPhysicalGeometryExit=sum(strcmp({Runs.FailureClass},'PHYSICAL_GEOMETRY_DOMAIN_EXIT'));M.NQPSolverFailure=sum(strcmp({Runs.FailureClass},'MATCHED_QP_SOLVER_FAILURE'));M.NReferenceNormalizedFail=sum([Runs.Completed]&~[Runs.ReferenceNormalizedPass]);M.NBackupSetFail=sum([Runs.Completed]&~[Runs.BackupSetPass]);M.NQPKKTGateFail=sum([Runs.Completed]&~[Runs.QPKKTGatePass]);
idx=[Runs.CorePass];if any(idx),M.PosRMSFullQ=w2e_quantiles([Runs(idx).PosRMSFull_m],[.50 .95 .99]);M.PosPeakLateQ=w2e_quantiles([Runs(idx).PosPeakLate_m],[.50 .95 .99]);M.AttitudeTubeQ=w2e_quantiles([Runs(idx).MaxAttitudeTube_deg],[.50 .95 .99]);M.InterventionPctQ=w2e_quantiles([Runs(idx).GovInterventionPct],[.50 .95 .99]);M.IntegratedObjectiveQ=w2e_quantiles([Runs(idx).IntegratedObjective_s],[.50 .95 .99]);else,M.PosRMSFullQ=[NaN NaN NaN];M.PosPeakLateQ=[NaN NaN NaN];M.AttitudeTubeQ=[NaN NaN NaN];M.InterventionPctQ=[NaN NaN NaN];M.IntegratedObjectiveQ=[NaN NaN NaN];end
end
